import React, { useEffect } from 'react'
import UserLayout from "@/layout/userLayout";
import DashboardLayout from "@/layout/dashboardLayout";
import { useDispatch, useSelector } from 'react-redux';
import { getMyConnectionRequest } from '@/config/redux/action/authAction';
imp

export default function MyConnectionsPage() {

    const dispatch = useDispatch();
    const authState = useSelector((state) => state.auth);

    useEffect(() => {
        dispatch(getMyConnectionRequest({ token: localStorage.getItem("token") }));
    }, []);

    useEffect(() => {

        if (authState.connectionRequest.length != 0) {
            console.log(authState.connectionRequest);
        }

    }, [authState.connectionRequest]);

    return (
        <UserLayout>
            <DashboardLayout>
                <div>
                    <h1>My connections</h1>

                    {Array.isArray(authState.connectionRequest) &&
                        authState.connectionRequest.length != 0 &&
                        authState.connectionRequest.map((user) => {
                            return (
                                <div className={styles.userCard} key={index}>
                                    <div style={{display:"flex", alignItems:"center"}}>
                                        <div className={styles.profilePicturer}>
                                            <img src={`${BASE_URL}/${user.userId.profilePic}`} alt="" />
                                        </div>
                                        <div className={styles.userInfo}>
                                            <h3>{user.userId.name}</h3>
                                            <p>{user.userId.username}</p>
                                        </div>
                                    </div>
                                </div>
                            )
                        })}
                </div>
            </DashboardLayout>
        </UserLayout>
    )
}
